function initProceduralFilmGrain() {
  const canvas = document.getElementById('film-grain-canvas');
  if (!canvas) return;
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    canvas.style.display = 'none';
    return;
  }
  const ctx = canvas.getContext('2d', { alpha: true });
  if (!ctx) return;
  const patternSize = 256;
  const patternCanvas = document.createElement('canvas');
  patternCanvas.width = patternSize;
  patternCanvas.height = patternSize;
  const patternCtx = patternCanvas.getContext('2d');
  const noiseTiles = [];
  const totalTiles = 6;
  for (let t = 0; t < totalTiles; t++) {
    const imgData = patternCtx.createImageData(patternSize, patternSize);
    const data = imgData.data;
    const len = data.length;
    for (let i = 0; i < len; i += 4) {
      const v = (Math.random() * 255) | 0;
      data[i] = v;
      data[i + 1] = v;
      data[i + 2] = v;
      data[i + 3] = (Math.random() * 45 + 20) | 0; // High-density grain
    }
    noiseTiles.push(imgData);
  }
  let width = (canvas.width = window.innerWidth);
  let height = (canvas.height = window.innerHeight);
  window.addEventListener('resize', () => {
    width = canvas.width = window.innerWidth;
    height = canvas.height = window.innerHeight;
  });
  let frame = 0;
  let lastTime = performance.now();
  const fpsInterval = 1000 / 24; // 24fps cinematic shutter rate
  function render(now) {
    requestAnimationFrame(render);
    const elapsed = now - lastTime;
    if (elapsed < fpsInterval) return;
    lastTime = now - (elapsed % fpsInterval);
    frame = (frame + 1) % totalTiles;
    patternCtx.putImageData(noiseTiles[frame], 0, 0);
    ctx.clearRect(0, 0, width, height);
    const pattern = ctx.createPattern(patternCanvas, 'repeat');
    if (pattern) {
      ctx.fillStyle = pattern;
      ctx.fillRect(0, 0, width, height);
    }
  }
  requestAnimationFrame(render);
}
function initGrainToggle() {
  const toggleBtn = document.getElementById('grain-toggle-btn');
  const canvas = document.getElementById('film-grain-canvas');
  if (!toggleBtn || !canvas) return;
  let isEnabled = true;
  toggleBtn.addEventListener('click', () => {
    isEnabled = !isEnabled;
    if (isEnabled) {
      canvas.style.display = 'block';
      toggleBtn.classList.add('active');
      toggleBtn.innerHTML = '<span>GRAIN: 35MM [ON]</span>';
    } else {
      canvas.style.display = 'none';
      toggleBtn.classList.remove('active');
      toggleBtn.innerHTML = '<span>GRAIN: OFF</span>';
    }
  });
}
function initCursorSpotlight() {
  let ticking = false;
  window.addEventListener('pointermove', (e) => {
    if (!ticking) {
      window.requestAnimationFrame(() => {
        document.documentElement.style.setProperty('--mouse-x', `${e.clientX}px`);
        document.documentElement.style.setProperty('--mouse-y', `${e.clientY}px`);
        ticking = false;
      });
      ticking = true;
    }
  }, { passive: true });
}
function initLiveCountdown() {
  const daysEl = document.getElementById('hud-days');
  const hoursEl = document.getElementById('hud-hours');
  const minsEl = document.getElementById('hud-mins');
  const secsEl = document.getElementById('hud-secs');
  if (!daysEl || !hoursEl || !minsEl || !secsEl) return;
  const targetDate = new Date('2026-09-06T09:30:00+05:30').getTime();
  function update() {
    const now = Date.now();
    const diff = Math.max(0, targetDate - now);
    const d = Math.floor(diff / (1000 * 60 * 60 * 24));
    const h = Math.floor((diff / (1000 * 60 * 60)) % 24);
    const m = Math.floor((diff / (1000 * 60)) % 60);
    const s = Math.floor((diff / 1000) % 60);
    daysEl.textContent = String(d).padStart(2, '0');
    hoursEl.textContent = String(h).padStart(2, '0');
    minsEl.textContent = String(m).padStart(2, '0');
    secsEl.textContent = String(s).padStart(2, '0');
  }
  update();
  setInterval(update, 1000);
}
function initMatchFilters() {
  const formatButtons = document.querySelectorAll('.format-filter-pill');
  const seasonButtons = document.querySelectorAll('.season-filter-pill');
  const resultButtons = document.querySelectorAll('.result-filter-pill');
  const searchInput = document.getElementById('match-search-field');
  const resetBtn = document.getElementById('match-filter-reset');
  const matchCards = document.querySelectorAll('.match-card');
  const countEl = document.getElementById('visible-matches-count');
  if (!matchCards.length) return;
  let activeFormat = 'all';
  let activeSeason = 'all';
  let activeResult = 'all';
  let searchQuery = '';
  function applyFilters() {
    let visibleCount = 0;
    matchCards.forEach((card) => {
      const fmt = (card.getAttribute('data-format') || '').toUpperCase();
      const season = card.getAttribute('data-season') || '';
      const result = card.getAttribute('data-result') || '';
      const text = card.textContent.toLowerCase();
      const formatMatches =
        activeFormat === 'all' ||
        ((activeFormat === '50-overs' || activeFormat === 'ODI') && (fmt.includes('50') || fmt.includes('ODI') || fmt.includes('ONE-DAY'))) ||
        (activeFormat === 'T20' && fmt.includes('T20'));
      const seasonMatches = activeSeason === 'all' || season === activeSeason;
      const resultMatches = activeResult === 'all' || result === activeResult;
      const searchMatches = !searchQuery || text.includes(searchQuery);
      if (formatMatches && seasonMatches && resultMatches && searchMatches) {
        card.style.display = 'flex';
        visibleCount++;
      } else {
        card.style.display = 'none';
      }
    });
    if (countEl) {
      countEl.textContent = visibleCount;
    }
  }
  formatButtons.forEach((btn) => {
    btn.addEventListener('click', () => {
      formatButtons.forEach((b) => b.classList.remove('active'));
      btn.classList.add('active');
      activeFormat = btn.getAttribute('data-format') || 'all';
      applyFilters();
    });
  });
  seasonButtons.forEach((btn) => {
    btn.addEventListener('click', () => {
      seasonButtons.forEach((b) => b.classList.remove('active'));
      btn.classList.add('active');
      activeSeason = btn.getAttribute('data-season') || 'all';
      applyFilters();
    });
  });
  resultButtons.forEach((btn) => {
    btn.addEventListener('click', () => {
      resultButtons.forEach((b) => b.classList.remove('active'));
      btn.classList.add('active');
      activeResult = btn.getAttribute('data-result') || 'all';
      applyFilters();
    });
  });
  if (searchInput) {
    searchInput.addEventListener('input', (e) => {
      searchQuery = e.target.value.toLowerCase().trim();
      applyFilters();
    });
  }
  if (resetBtn) {
    resetBtn.addEventListener('click', () => {
      activeFormat = 'all';
      activeSeason = 'all';
      activeResult = 'all';
      searchQuery = '';
      if (searchInput) searchInput.value = '';
      formatButtons.forEach((b) => b.classList.toggle('active', b.getAttribute('data-format') === 'all'));
      seasonButtons.forEach((b) => b.classList.toggle('active', b.getAttribute('data-season') === 'all'));
      resultButtons.forEach((b) => b.classList.toggle('active', b.getAttribute('data-result') === 'all'));
      applyFilters();
    });
  }
}
function initSquadRoleFilter() {
  const searchInput = document.getElementById('squad-search-input');
  const clearBtn = document.getElementById('squad-search-clear');
  const suggestChips = document.querySelectorAll('.squad-suggest-chip');
  const countDisplay = document.getElementById('squad-count-display');
  const roleButtons = document.querySelectorAll('.role-filter-pill');
  const playerCards = document.querySelectorAll('.jersey-player-card, .fifa-player-card');
  if (!playerCards.length) return;
  function filterCards(query) {
    const q = (query || '').toLowerCase().trim();
    let visibleCount = 0;
    playerCards.forEach((card) => {
      const searchData = (card.getAttribute('data-search') || '').toLowerCase();
      const cardRole = (card.getAttribute('data-role') || '').toLowerCase();
      const cardName = (card.getAttribute('data-name') || '').toLowerCase();
      const cardNum = (card.getAttribute('data-number') || '').toLowerCase();
      const cardStyle = (card.getAttribute('data-style') || '').toLowerCase();
      const allText = `${searchData} ${cardRole} ${cardName} ${cardNum} ${cardStyle}`;
      let matches = false;
      if (!q || q === 'all') {
        matches = true;
      } else if (q === 'captain') {
        matches = cardRole.includes('captain') || cardRole.includes('all-rounder');
      } else if (q === 'bat' || q === 'batter' || q === 'batters') {
        matches = cardRole.includes('batter') || cardRole.includes('bat');
      } else if (q === 'bowl' || q === 'bowler' || q === 'bowlers') {
        matches = cardRole.includes('bowler') || cardRole.includes('bowl');
      } else if (q === 'wicket' || q === 'wicketkeeper' || q === 'wicketkeepers') {
        matches = cardRole.includes('wicket');
      } else {
        const terms = q.split(/\s+/).filter(Boolean);
        matches = terms.every(t => allText.includes(t));
      }
      if (matches) {
        card.style.display = 'flex';
        visibleCount++;
      } else {
        card.style.display = 'none';
      }
    });
    if (countDisplay) {
      if (!q || q === 'all') {
        countDisplay.innerHTML = `Showing all <strong>${playerCards.length}</strong> players`;
      } else {
        countDisplay.innerHTML = `Found <strong>${visibleCount}</strong> of ${playerCards.length} players for "<em>${query}</em>"`;
      }
    }
  }
  if (searchInput) {
    searchInput.addEventListener('input', (e) => {
      filterCards(e.target.value);
    });
  }
  if (clearBtn && searchInput) {
    clearBtn.addEventListener('click', () => {
      searchInput.value = '';
      filterCards('');
      searchInput.focus();
    });
  }
  suggestChips.forEach((chip) => {
    chip.addEventListener('click', () => {
      const val = chip.getAttribute('data-search');
      if (searchInput) {
        searchInput.value = val;
        filterCards(val);
        searchInput.focus();
      } else {
        filterCards(val);
      }
    });
  });
  if (roleButtons.length) {
    roleButtons.forEach((btn) => {
      btn.addEventListener('click', () => {
        roleButtons.forEach((b) => b.classList.remove('active'));
        btn.classList.add('active');
        const role = btn.getAttribute('data-role');
        filterCards(role);
      });
    });
  }
}
function initMobileMenu() {
  const menuBtn = document.getElementById('mobile-menu-btn');
  const drawer = document.getElementById('mobile-menu-drawer');
  if (!menuBtn || !drawer) return;
  menuBtn.addEventListener('click', () => {
    const isExpanded = menuBtn.getAttribute('aria-expanded') === 'true';
    menuBtn.setAttribute('aria-expanded', !isExpanded);
    drawer.style.display = isExpanded ? 'none' : 'flex';
  });
}
